SourceCode.Declaration:
/// <summary>
/// Entry point for the Publish action. Dispatches to the appropriate type-specific
/// publishing class which writes versioned values back into the live parameter tables.
/// Called both from the action menu item and automatically via the SystemParameters::find() extension.
/// </summary>
internal final class AAXParameterPublish
{
}

Method.Source:
public static void main(Args _args)
{
    AAXParameterPublish_SystemParameters AAXParameterPublish_SystemParameters = new AAXParameterPublish_SystemParameters();

    AAXParameterPublish_SystemParameters.run(_args.record());

    // Refresh the calling form so published changes are reflected
    FormDataSource fds = FormDataUtil::getFormDataSource(_args.record());
    if(fds)
    {
        fds.research(true);
    }
}
